<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {api,useLearning} from '../useLearning.js'
import {useDialogFocus} from '../useDialogFocus.js'
import RecordPagination from './ui/RecordPagination.vue'
import {usePagination} from '../usePagination.js'
const props=defineProps({courseId:String})
const emit=defineEmits(['close'])
const {state,openCourse}=useLearning(),dialog=ref(null),data=ref(null),error=ref(''),loading=ref(false)
useDialogFocus(dialog)
let version=0
const chapters=computed(()=>data.value?.lessons.filter(l=>l.chapter).sort((a,b)=>a.chapter-b.chapter)||[])
const foundations=computed(()=>data.value?.lessons.filter(l=>!l.chapter)||[])
const {page:chapterPage,items:chapterRows}=usePagination(chapters,()=>props.courseId)
async function load(){const v=++version;loading.value=true;error.value='';try{const r=await api('/catalog/'+props.courseId);if(v===version)data.value=r}catch(e){if(v===version)error.value=e.message}finally{if(v===version)loading.value=false}}
async function start(id){await openCourse(props.courseId,id);if(!state.error)emit('close')}
onMounted(load);onUnmounted(()=>++version)
</script>
<template><dialog ref="dialog" class="course-outline-dialog" aria-label="课程目录与课程依据" @cancel.prevent="emit('close')"><button class="dialog-close" aria-label="关闭课程目录" @click="emit('close')">×</button><p v-if="loading" role="status">正在读取课程目录…</p><p v-if="error" class="inline-error" role="alert">{{ error }} <button @click="load">重新读取</button></p><template v-if="data"><span class="course-tag" :class="data.tint">{{ data.tag }}</span><h1>{{ data.title }}</h1><p>{{ data.description }}</p><section class="course-reference"><h2>课程依据</h2><strong>{{ data.reference.title }}</strong><p>{{ data.reference.authors }}{{ data.reference.publisher?' · '+data.reference.publisher:'' }}{{ data.reference.isbn?' · ISBN '+data.reference.isbn:'' }}</p><p>{{ data.reference.usage }}</p><a :href="data.reference.url" target="_blank" rel="noopener noreferrer">查看原教材／课程依据</a></section><p class="course-route-note">先用诊断确认起点。已理解的内容可换题复核；卡住时回看例子、获得帮助并做补救。自己的解释会保留，长期保持需间隔后再检查。</p><h2>核心学习路线 · {{ chapters.length }} 个单元</h2><ol class="course-outline-units"><li v-for="lesson in chapterRows" :key="lesson.id"><div><small>{{ String(lesson.chapter).padStart(2,'0') }} · {{ lesson.minutes }} 分钟</small><h3>{{ lesson.title }}</h3><p>{{ lesson.objective }}</p><span>诊断 · 讲义 · 练习 · 补救 · 换题复核 · 解释</span></div><button class="secondary-button" @click="start(lesson.id)">从这里学习</button></li></ol><RecordPagination v-model="chapterPage" :total="chapters.length" label="课程核心目录"/><details v-if="foundations.length"><summary>基础专题与已保留的学习单元 · {{ foundations.length }} 个</summary><button v-for="lesson in foundations" :key="lesson.id" class="course-foundation-link" @click="start(lesson.id)">{{ lesson.title }} <span>打开学习</span></button></details><footer><small>中文讲义与题目为知行伴学自编；目录对齐不代表原机构认证或授课授权。</small><button class="primary-button" @click="start(chapters[0]?.id)">从第一单元开始</button></footer></template></dialog></template>
<style scoped>
.course-outline-dialog{width:min(900px,94vw);max-height:88dvh;border:1px solid #dce7dc;border-radius:16px;padding:30px;color:#315a48}.course-outline-dialog h1{font:28px/1.6 SimSun;margin:15px 0}.course-outline-dialog>p{font-size:14px;line-height:1.9}.course-outline-dialog h2{font-size:19px}.course-reference{background:#f2f6ed;border-radius:10px;padding:16px 20px;margin:22px 0}.course-reference h2{font-size:16px;margin:0 0 12px}.course-reference p{font-size:12px;color:#73856b;line-height:1.9;margin:8px 0}.course-reference a{font-size:12px;color:#32715a}.course-route-note{border-left:3px solid #91b185;padding:6px 14px;color:#6b8363}.course-outline-units{list-style:none;padding:0}.course-outline-units li{display:flex;gap:18px;align-items:center;justify-content:space-between;border-bottom:1px solid #e5ece0;padding:17px 0}.course-outline-units h3{font-size:17px;margin:7px 0}.course-outline-units p{font-size:13px;line-height:1.8;margin:7px 0}.course-outline-units small,.course-outline-units span{font-size:11px;color:#849778}.course-outline-units button{flex-shrink:0;font-size:12px}.course-outline-dialog summary{cursor:pointer;padding:16px;background:#f7f9f2;border-radius:8px}.course-foundation-link{display:flex;width:100%;justify-content:space-between;background:white;border:0;border-bottom:1px solid #e5ece0;padding:13px;text-align:left;color:#5e7c54}.course-foundation-link span{font-size:11px}.course-outline-dialog footer{display:flex;gap:20px;justify-content:space-between;align-items:center;margin-top:24px}.course-outline-dialog footer small{font-size:11px;line-height:1.8;color:#8b9b7c;max-width:55%}@media(max-width:550px){.course-outline-dialog{padding:22px}.course-outline-dialog h1{font-size:23px}.course-outline-units li{align-items:flex-start;flex-direction:column}.course-outline-dialog footer{flex-direction:column}.course-outline-dialog footer small{max-width:none}}
</style>
